import json


def protocol_version():
    return "2.4.1"


def export_jsonl(message):
    payload = {
        "schema": "chat-jsonl-v2",
        "role": message["role"],
        "content": message["content"],
    }
    return json.dumps(payload, separators=(",", ":")) + "\n"

