from eval_protocol import protocol_version


def client_version():
    return "0.14.2"


def adapter_name():
    return "openai-compatible-r42"


def decode_chat_message(payload):
    if protocol_version() != "2.4.1":
        raise RuntimeError("current adapter requires eval-protocol 2.4.1")
    message = payload["message"]
    return {"role": message["role"], "content": message["content"]}


def decode_legacy_transcript(payload):
    raise RuntimeError("legacy provider transcript decoding was removed from the r42 adapter")

from eval_protocol import protocol_version


def client_version():
    return "0.13.5"


def adapter_name():
    return "legacy-provider-transcript"


def decode_chat_message(payload):
    raise RuntimeError("legacy adapter does not accept chat-jsonl-v2 messages")


def decode_legacy_transcript(payload):
    if protocol_version() != "2.3.0":
        raise RuntimeError("legacy transcript decoder requires eval-protocol 2.3.0")
    return payload["completion"]["text"]
